import{_ as t,o,c as s,a3 as a}from"./chunks/framework.B02wg2PO.js";const k=JSON.parse('{"title":"Connecting a Repo","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart/connecting-a-repo.md","filePath":"quickstart/connecting-a-repo.md"}'),i={name:"quickstart/connecting-a-repo.md"};function n(r,e,d,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="connecting-a-repo" tabindex="-1">Connecting a Repo <a class="header-anchor" href="#connecting-a-repo" aria-label="Permalink to &quot;Connecting a Repo&quot;">​</a></h1><p>A <strong>project</strong> is a repo Saidi knows about. Registering one gives you a project agent scoped to that checkout, and a memory file that carries the repo&#39;s policy and its durable facts.</p><h2 id="register-the-project" tabindex="-1">Register the project <a class="header-anchor" href="#register-the-project" aria-label="Permalink to &quot;Register the project&quot;">​</a></h2><p>Ask PRIME in chat, or use the tools directly:</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td><code>discover_projects</code></td><td>Scans your configured scan roots for git repos</td></tr><tr><td><code>sync_projects</code></td><td>Reconciles the registry with what is on disk</td></tr><tr><td><code>add_project</code></td><td>Registers one repo explicitly (name + path)</td></tr><tr><td><code>list_projects</code></td><td>Shows the registry</td></tr><tr><td><code>update_project</code> / <code>remove_project</code></td><td>Edit or drop an entry</td></tr></tbody></table><p>The registry name you choose is what PRIME uses as the delegation target and as the <code>assignee</code> on checklist tasks — keep it short and unambiguous.</p><h2 id="set-the-project-s-policy" tabindex="-1">Set the project&#39;s policy <a class="header-anchor" href="#set-the-project-s-policy" aria-label="Permalink to &quot;Set the project&#39;s policy&quot;">​</a></h2><p>Each project&#39;s policy lives in the frontmatter of its memory file, <code>memory/projects/&lt;name&gt;.md</code>:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">branch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # new | current</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">approval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">confirm</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # confirm | auto</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">verify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">npm test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # optional: shell command run after a work delegation commits</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># my-app</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Purpose</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Values</th><th>Default</th></tr></thead><tbody><tr><td><code>branch</code></td><td><code>new</code> cuts a <code>saidi/*</code> branch and opens a PR; <code>current</code> commits on the checked-out branch</td><td><code>new</code></td></tr><tr><td><code>approval</code></td><td><code>confirm</code> asks before any write; <code>auto</code> proceeds without a prompt</td><td><code>confirm</code></td></tr><tr><td><code>verify</code></td><td>A shell command run after a work delegation commits. Pass/fail is reported mechanically</td><td>none</td></tr></tbody></table><p>There is <strong>no global default that silently applies</strong> — an unset, missing, or invalid value falls back to the built-in safe policy (<code>new</code> + <code>confirm</code>), unless you have changed the operator fallback in Settings → System. Parsing is lenient: unknown keys, inline <code># comments</code>, and quotes are ignored.</p><div class="tip custom-block"><p class="custom-block-title"><code>verify:</code> is the cheapest trust you will ever buy</p><p>With <code>verify: npm test</code> set, &quot;done&quot; stops being the agent&#39;s claim and becomes an exit code in the change note. Set it on every repo that has a test command.</p></div><h2 id="fill-in-the-memory-file" tabindex="-1">Fill in the memory file <a class="header-anchor" href="#fill-in-the-memory-file" aria-label="Permalink to &quot;Fill in the memory file&quot;">​</a></h2><p>Below the frontmatter, the memory file is free-form markdown that gets injected into the project agent&#39;s prompt. Worth recording:</p><ul><li><strong>Purpose</strong> — what the repo is, in one line.</li><li><strong>Layout &amp; scripts</strong> — top-level dirs, and the <code>dev</code> / <code>build</code> / <code>test</code> commands.</li><li><strong>Deploy steps</strong> — the exact procedure, if there is one.</li><li><strong>Notes / gotchas</strong> — required env vars, ports, things that break.</li></ul><p>Memory is <em>not</em> committed to your repo. It lives in Saidi under <code>memory/projects/</code>, so your repo stays clean and the knowledge follows the operator.</p><h2 id="first-delegation" tabindex="-1">First delegation <a class="header-anchor" href="#first-delegation" aria-label="Permalink to &quot;First delegation&quot;">​</a></h2><p>Start with an <code>ask</code> — a read-only investigation — before you let anything write:</p><blockquote><p>Ask my-app: what does the auth middleware do, and where is the session validated?</p></blockquote><p>An <code>ask</code> delegation runs the project agent with a read-only tool set (<code>Read</code>, <code>Grep</code>, <code>Glob</code>). When you are satisfied it understands the repo, promote to <code>work</code>.</p><p>Next: <a href="/docs/concepts/runs">Runs</a>.</p>`,21)])])}const g=t(i,[["render",n]]);export{k as __pageData,g as default};
